class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)

        def almost_equal(a, b):
            if a == b:
                return True
            return abs(ord(a) - ord(b)) == 1

        # dp[i][prev] = minimum changes needed for substring starting at i
        # when the previous character chosen is prev
        # prev is in range 0-26 (26 means no previous character)
        from functools import lru_cache

        @lru_cache(None)
        def dp(i, prev):
            if i == n:
                return 0
            res = float('inf')
            for c in range(26):
                ch = chr(ord('a') + c)
                if prev != 26:
                    prev_ch = chr(ord('a') + prev)
                    if almost_equal(ch, prev_ch):
                        continue
                cost = 0 if ch == word[i] else 1
                res = min(res, dp(i + 1, c) + cost)
            return res

        return dp(0, 26)
